begin;
do $curate$ declare bid uuid;begin
if exists(select 1 from public.businesses where website ilike '%pamperedpettracy%' or name ilike '%pampered pet%' or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%2098337600') then raise exception 'Duplicate provider requires review';end if;
insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('The Pampered Pet Grooming & Spa','Pet Services','Tracy','1872 W 11th Street, Tracy, CA 95376','(209) 833-7600','https://www.pamperedpettracy.com/','Tracy grooming salon whose official website also advertises mobile grooming in the Central Valley. Confirm your pet''s needs, quote, appointment and exact mobile coverage directly. Coverage for Mountain House, Lathrop and Manteca has not been individually established.','approved',true,false,null,0,'editorial_first_party','https://www.pamperedpettracy.com/pages/contact','first_party_website_desk_check',now()) returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.pamperedpettracy.com/pages/contact',array['identity','website','public phone','address','advertised services'],array['Tracy'],array['dog grooming','mobile dog grooming'],'Newspaper printed-page29 lead independently checked against official website contact and services. Tracy salon established; Central Valley mobile advertisement does not establish each surrounding city. No credential, safety, quality, price or appointment guarantee. No images copied. Sources: https://www.pamperedpettracy.com/pages/contact https://www.pamperedpettracy.com/ https://www.pamperedpettracy.com/pages/services');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name":"The Pampered Pet Grooming & Spa","website":"https://www.pamperedpettracy.com/","phone":"(209) 833-7600","address":"1872 W 11th Street, Tracy, CA 95376","description":"Tracy grooming salon whose official website also advertises mobile grooming in the Central Valley. Confirm your pet''s needs, quote, appointment and exact mobile coverage directly. Coverage for Mountain House, Lathrop and Manteca has not been individually established.","sources":["https://www.pamperedpettracy.com/pages/contact","https://www.pamperedpettracy.com/","https://www.pamperedpettracy.com/pages/services"]}'::jsonb,'Newspaper lead independently verified with first-party contact page','https://www.pamperedpettracy.com/pages/contact');
end $curate$;
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Fall Lanterns for Grades 6–12','Students in grades 6–12 can make a fall lantern using a mason jar, pressed flowers and acrylic paint. Official occurrence, grade range and room checked November 8, 2026. Confirm attendance and materials arrangements directly with the library.','Tracy','Tracy Branch Library, Wadsworth Room, 20 E Eaton Avenue, Tracy','2026-11-16T16:00:00-08:00','2026-11-16T17:00:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/tracy/november-2026/fall-lanterns-for-grades-6-12?id=1794873600-246213','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Tracy' and source_url='https://www.ssjcpl.org/events-services/events-calendar/tracy/november-2026/fall-lanterns-for-grades-6-12?id=1794873600-246213' and start_date='2026-11-16T16:00:00-08:00'::timestamptz);
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'DIY Winter Crafts (Ages 3–7)','Winter craft-making program for children ages 3–7. Exact December 4 occurrence, audience and branch location checked November 8, 2026 on the library''s official page. Confirm attendance and any registration requirements directly.','Manteca','Manteca Branch Library, 320 W Center Street, Manteca','2026-12-04T15:00:00-08:00','2026-12-04T16:00:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/manteca-branch/diy-winter-crafts?id=1796425200-245768','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Manteca' and source_url='https://www.ssjcpl.org/events-services/events-calendar/manteca-branch/diy-winter-crafts?id=1796425200-245768' and start_date='2026-12-04T15:00:00-08:00'::timestamptz);
commit;
